using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Cms;
using Shop.Modules.Identity;
using Xunit;
namespace Shop.SqlTests;
public sealed class SupportContentSqlTests:IAsyncLifetime
{
    private readonly SqlFixture sql=new();
    public Task InitializeAsync()=>sql.InitializeAsync();public Task DisposeAsync()=>sql.DisposeAsync();
    private static JsonObject Content(string title="راهنمای نمونهٔ QA",bool demo=true)=>new(){["schemaVersion"]=1,["isDemo"]=demo,["eyebrow"]="نمونهٔ مستقل",["title"]=title,["description"]="نمونهٔ SQL موقت؛ سیاست تجاری نیست",["ticketsAction"]="ارسال تیکت",["faqTitle"]="پرسش‌های نمونه",["faqDescription"]="",["faqs"]=new JsonArray(new JsonObject{["id"]=new string('a',32),["question"]="سؤال نمونهٔ منتشرشده؟",["answer"]="<b>متن ساده</b>\nپاسخ فقط برای آزمون",["enabled"]=true},new JsonObject{["id"]=new string('b',32),["question"]="این سؤال نباید عمومی شود؟",["answer"]="محتوای غیرفعال خصوصی",["enabled"]=false})};
    private static async Task<JsonNode> Body(HttpResponseMessage response,string? capture=null)
    {
        using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());if(capture is not null&&Environment.GetEnvironmentVariable("SHOP_SUPPORT_CONTENT_WIRE_DIR") is{Length:>0}dir){Directory.CreateDirectory(dir);await File.WriteAllTextAsync(Path.Combine(dir,capture+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,capture+".meta.json"),System.Text.Json.JsonSerializer.Serialize(new{method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery,status=(int)response.StatusCode,actualSqlHttpResponse=true,syntheticQaOnly=true}));}return JsonNode.Parse(raw)!;}
    }
    private async Task<HttpClient> Staff(string role="ContentManager")
    {
        await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="supportcms"+Guid.NewGuid().ToString("N");var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(user,role)).Succeeded);
        var c=sql.Factory.CreateClient(new(){HandleCookies=false});c.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");c.DefaultRequestHeaders.Add("X-Sayman-Client","admin");c.DefaultRequestHeaders.Add("X-Sayman-Admin","1");var pending=await Body(await c.PostAsJsonAsync("/api/auth/password",new{Identifier=name,Password=sql.Password}));c.DefaultRequestHeaders.Authorization=new("Bearer",pending["accessToken"]!.GetValue<string>());var setup=await Body(await c.PostAsJsonAsync("/api/auth/mfa/setup",new{}));c.DefaultRequestHeaders.Authorization=new("Bearer",setup["accessToken"]!.GetValue<string>());var signed=await Body(await c.PostAsJsonAsync("/api/auth/mfa/verify",new{Code=Totp.Code(setup["secret"]!.GetValue<string>(),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30)}));c.DefaultRequestHeaders.Authorization=new("Bearer",signed["accessToken"]!.GetValue<string>());return c;
    }
    private static async Task Saved(HttpResponseMessage response){using(response)Assert.Equal(HttpStatusCode.NoContent,response.StatusCode);await Task.CompletedTask;}
    private static async Task<JsonNode> Document(HttpClient c,string locale){var all=await Body(await c.GetAsync("/api/admin/content"));return all["documents"]!.AsArray().Single(x=>x!["key"]!.GetValue<string>()=="support"&&x["locale"]!.GetValue<string>()==locale)!;}
    private static async Task Publish(HttpClient c,JsonNode doc,string? restore=null)=>await Saved(await c.PostAsJsonAsync("/api/admin/content/support/"+doc["locale"]!.GetValue<string>()+"/publish",new{Version=doc["version"]!.GetValue<string>(),RestoreRevisionId=restore}));
    [Fact]public async Task DraftPublishDisabledFaqLocaleAndRestoreUseOnlyExplicitPublishedContent()
    {
        using var publicClient=sql.Factory.CreateClient(new(){HandleCookies=false});using var staff=await Staff();var missing=await Body(await publicClient.GetAsync("/api/content/support/fa"),"missing");Assert.Null(missing["content"]);Assert.Equal(0,missing["revision"]!.GetValue<int>());var original=Content();await Saved(await staff.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(original,null)));
        Assert.Null((await Body(await publicClient.GetAsync("/api/content/support/fa"),"draft-hidden"))["content"]);var doc=await Document(staff,"fa");await Publish(staff,doc);var published=await Body(await publicClient.GetAsync("/api/content/support/fa"),"published-fa");Assert.Equal(1,published["revision"]!.GetValue<int>());Assert.Single(published["content"]!["faqs"]!.AsArray());Assert.DoesNotContain("محتوای غیرفعال خصوصی",published.ToJsonString());Assert.DoesNotContain("enabled",published.ToJsonString());Assert.DoesNotContain("updatedBy",published.ToJsonString());Assert.True(published["content"]!["isDemo"]!.GetValue<bool>());
        var en=await Body(await publicClient.GetAsync("/api/content/support/en"),"no-locale-fallback");Assert.Null(en["content"]);
        await using(var scope=sql.Factory.Services.CreateAsyncScope())Assert.Null((await new SupportContentReader(scope.ServiceProvider.GetRequiredService<CmsDbContext>(),false).ReadAsync("fa",default)).Content);
        await Saved(await staff.PutAsJsonAsync("/api/admin/content/support/en",new ContentInput(Content("Synthetic QA English guide",false),null)));await Publish(staff,await Document(staff,"en"));await Body(await publicClient.GetAsync("/api/content/support/en"),"published-en");
        await using(var scope=sql.Factory.Services.CreateAsyncScope())Assert.Equal("Synthetic QA English guide",(await new SupportContentReader(scope.ServiceProvider.GetRequiredService<CmsDbContext>(),false).ReadAsync("en",default)).Content!.Title);
        doc=await Document(staff,"fa");var changed=Content("ویرایش دومِ نمونه");await Saved(await staff.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(changed,doc["version"]!.GetValue<string>())));Assert.Equal(published.ToJsonString(),(await Body(await publicClient.GetAsync("/api/content/support/fa"),"unpublished-edit-hidden")).ToJsonString());
        await Publish(staff,await Document(staff,"fa"));Assert.Equal(2,(await Body(await publicClient.GetAsync("/api/content/support/fa"),"revision-two"))["revision"]!.GetValue<int>());
        var all=await Body(await staff.GetAsync("/api/admin/content"));var revision=all["revisions"]!.AsArray().Single(x=>x!["key"]!.GetValue<string>()=="support"&&x["locale"]!.GetValue<string>()=="fa"&&x["revision"]!.GetValue<int>()==1)!;var historical=await Body(await staff.GetAsync("/api/admin/content/support/fa/revisions/"+revision["id"]!.GetValue<string>()),"historical-revision");Assert.Equal(original.ToJsonString(),historical["content"]!.ToJsonString());using(var wrongLocale=await staff.GetAsync("/api/admin/content/support/en/revisions/"+revision["id"]!.GetValue<string>()))Assert.Equal(HttpStatusCode.NotFound,wrongLocale.StatusCode);await Publish(staff,await Document(staff,"fa"),revision["id"]!.GetValue<string>());var restored=await Body(await publicClient.GetAsync("/api/content/support/fa"),"restored");Assert.Equal(3,restored["revision"]!.GetValue<int>());Assert.Equal(published["content"]!.ToJsonString(),restored["content"]!.ToJsonString());
        var foreign=all["revisions"]!.AsArray().Single(x=>x!["key"]!.GetValue<string>()=="support"&&x["locale"]!.GetValue<string>()=="en")!;doc=await Document(staff,"fa");using(var denied=await staff.PostAsJsonAsync("/api/admin/content/support/fa/publish",new{Version=doc["version"]!.GetValue<string>(),RestoreRevisionId=foreign["id"]!.GetValue<string>()}))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);Assert.Equal(restored.ToJsonString(),(await Body(await publicClient.GetAsync("/api/content/support/fa"))).ToJsonString());
    }
    [Fact]public async Task SupportAgentCannotManageEditorialContentAndPublicReadsRejectDraftQueries()
    {
        using var support=await Staff("SupportAgent");using(var denied=await support.GetAsync("/api/admin/content"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var denied=await support.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(Content(),null)))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using(var denied=await support.GetAsync("/api/admin/content/support/fa/revisions/1"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);using var editor=await Staff();using(var denied=await editor.GetAsync("/api/admin/support/tickets"))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
        using var publicClient=sql.Factory.CreateClient(new(){HandleCookies=false});using(var denied=await publicClient.GetAsync("/api/admin/content/support/fa/revisions/1"))Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);foreach(var badId in new[]{"0","01","9223372036854775808","-1"}){using var invalid=await editor.GetAsync("/api/admin/content/support/fa/revisions/"+badId);Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);}using(var query=await editor.GetAsync("/api/admin/content/support/fa/revisions/1?draft=true"))Assert.Equal(HttpStatusCode.BadRequest,query.StatusCode);foreach(var path in new[]{"/api/content/support/fa?draft=true","/api/content/support/en?owner=other","/api/content/support/zz"}){using var invalid=await publicClient.GetAsync(path);Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);}
        var wrong=Content();wrong["faqs"]![0]!["answer"]=new string('a',4001);using(var invalid=await editor.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(wrong,null)))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.False(await scope.ServiceProvider.GetRequiredService<CmsDbContext>().Documents.AnyAsync(x=>x.Key=="support"));
    }
    [Fact]public async Task AuditFailureRollsBackPublicationAndItsRevisionBeforeRetry()
    {
        using var editor=await Staff();await Saved(await editor.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(Content(),null)));var doc=await Document(editor,"fa");
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<Shop.Modules.Identity.IdentityDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT [CK_SupportContentAuditFailure] CHECK ([Resource]<>N'/api/admin/content/support/fa/publish')");}
        try{using var failed=await editor.PostAsJsonAsync("/api/admin/content/support/fa/publish",new{Version=doc["version"]!.GetValue<string>(),RestoreRevisionId=(string?)null});Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<Shop.Modules.Identity.IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT [CK_SupportContentAuditFailure]");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CmsDbContext>();var row=await db.Documents.AsNoTracking().SingleAsync(x=>x.Key=="support");Assert.Equal(0,row.Revision);Assert.Null(row.PublishedJson);Assert.False(await db.Revisions.AnyAsync(x=>x.Key=="support"));Assert.Equal(doc["version"]!.GetValue<string>(),Convert.ToBase64String(row.Version));}
        await Publish(editor,doc);
    }
    [Fact]public async Task ConcurrentPublishWithTheSameVersionCannotAddTwoRevisions()
    {
        using var editor=await Staff();await Saved(await editor.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(Content(),null)));var doc=await Document(editor,"fa");var input=new{Version=doc["version"]!.GetValue<string>(),RestoreRevisionId=(string?)null};var results=await Task.WhenAll(editor.PostAsJsonAsync("/api/admin/content/support/fa/publish",input),editor.PostAsJsonAsync("/api/admin/content/support/fa/publish",input));Assert.Single(results,x=>x.StatusCode==HttpStatusCode.NoContent);Assert.Single(results,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var response in results)response.Dispose();await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Single(await scope.ServiceProvider.GetRequiredService<CmsDbContext>().Revisions.Where(x=>x.Key=="support").ToArrayAsync());
    }
    [Fact]public async Task CorruptOrOversizedPublishedJsonFailsClosedInsteadOfShowingDraftOrAnotherLanguage()
    {
        using var editor=await Staff();await Saved(await editor.PutAsJsonAsync("/api/admin/content/support/fa",new ContentInput(Content(),null)));await Publish(editor,await Document(editor,"fa"));using var publicClient=sql.Factory.CreateClient(new(){HandleCookies=false});
        foreach(var json in new[]{"{broken}",new string('a',100001),"{}",Content().ToJsonString()+new string(' ',100001)}){await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<CmsDbContext>().Documents.Where(x=>x.Key=="support"&&x.Locale=="fa").ExecuteUpdateAsync(s=>s.SetProperty(x=>x.PublishedJson,json));using var response=await publicClient.GetAsync("/api/content/support/fa");Assert.Equal(HttpStatusCode.ServiceUnavailable,response.StatusCode);var problem=await response.Content.ReadFromJsonAsync<JsonNode>();Assert.Equal("support_content_unavailable",problem!["title"]!.GetValue<string>());}
    }
}
